referenceSolutionTemplate:
#include <stdio.h>
#include <string.h>

int main(void) {
    char word[32];
    if (scanf("%31s", word) != 1) {
        printf("没接到词\n");
        return 1;
    }

    if (strcmp(word, "build") == 0) {
        printf("{a}\n");
        printf("{b}\n");
    } else if (strcmp(word, "clean") == 0) {
        printf("{c}\n");
        printf("{d}\n");
    } else if (strcmp(word, "tidy") == 0) {
        printf("{e}\n");
    } else {
        printf("认不得：%s\n", word);
    }
    return 0;
}
